function fn_ensure_cron_key():string{global $config;$key=trim((string)($config['cron_key']??''));if($key!=='')return$key;$key=bin2hex(random_bytes(32));$config['cron_key']=$key;$file=__DIR__.'/config.local.php';$php="<?php\nreturn ".var_export($config,true).";\n";if(file_put_contents($file,$php,LOCK_EX)===false)throw new RuntimeException('Não foi possível salvar a chave do CRON em api/config.local.php.');@chmod($file,0640);return$key;}
