function fn_system_cron_config(array $ctx):never{fn_require_master($ctx);$key=fn_ensure_cron_key();$url=fn_base_url().'/api/cron-runner.php?key='.rawurlencode($key);$command="curl -fsS ".escapeshellarg($url)." >/dev/null 2>&1";$full="* * * * * ".$command;out(['data'=>['success'=>true,'url'=>$url,'command'=>$command,'full_line'=>$full,'schedule'=>'* * * * *'],'error'=>null]);}
